import boto3

BEDROCK_REGION = 'us-west-2'

def get_bedrock_client():
    return boto3.client('bedrock', region_name=BEDROCK_REGION)

def get_model_id(model_family):
    model_ids = {
        'amazon-nova-api': 'amazon-nova-api/nova-pro-v1',
        'anthropic-claude': 'anthropic.claude-v2',
        'openai-gpt': 'openai.gpt-3.5-turbo'
    }
    return model_ids.get(model_family, None)

def configure_client(model_family):
    client = get_bedrock_client()
    model_id = get_model_id(model_family)
    if not model_id:
        raise ValueError(f'Model family {model_family} not supported')
    return client, model_id

import boto3

def stream_completion(prompt, model_id='amazon.titan-text-express-v1'):
    bedrock = boto3.client('bedrock-runtime')
    response = bedrock.invoke_model(
        model_id=model_id,
        body={
            'prompt': prompt,
            'maxTokens': 150,
            'temperature': 0.5
        }
    )
    for event in response['body']['stream']:
        yield event['token']

import boto3

def answer_with_context(question, context):
    bedrock_client = boto3.client('bedrock-runtime')
    response = bedrock_client.invoke_model(
        model_id='amazon.bedrock.model',
        body={
            'prompt': f"Answer the following question using the provided context: {question}. Context: {context}",
            'max_tokens': 150
        }
    )
    result = response['body'].read()
    return result.decode('utf-8')

